style.css:
@-moz-document domain("music.yandex.ru") {
.bar {
    height: 90px
}
.progress {
    top: -14px;
}
.player-controls .track {
    margin-left: 10px;
}
.player-controls__track-container {
    margin-left: 226px;
    top: 18px;
    left: 0;
    right: 342px !important;
}
.player-controls {
    top: 0;
    bottom: 0;

}
.player-controls__track-controls {
    margin: 0 0 0 0;
    top: -4px;
}
.player-controls .player-controls__btn,
.volume__btn,
.popup-sequence__close-wrapper,
.popup-sequence__buttons-bar .popup-sequence__button-clear,
.popup-sequence__buttons-bar .popup-sequence__button-save,
.d-addition__content {
    zoom: 1.5;
}
.player-controls .d-like,
.player-controls .dislike {
    padding-top: 0;
}
.volume__btn {
    padding-top: 3px;
    left: 8px;
}
.player-controls__track [class*=player-controls] .d-button,
.player-controls .player-controls__btn_share.d-button{
    padding-top: 6px;
}
.player-controls__wrapper {
    max-width: unset;
}
.player-controls__track_shown {
    width: 100%
}
.track {
    font-size: 15px;
}
.track_type_player .track__name {
    margin-top: 0;
}

.popup-sequence .popup__close {
    margin-right: 15px;
}
.popup-sequence .d-tabs .d-tabs__tab {
    height: 60px;
    line-height: 40px;
}
.popup-sequence__buttons-bar .popup-sequence__button-clear {
    opacity: .5;
}
.popup-sequence__buttons-bar .popup-sequence__button-clear > span {
    border: none !important;
    box-shadow: none !important;
    outline: none !important;
}
.popup-sequence .popup__close {
    opacity: 1 !important;
}
.theme-black .deco-button-flat .deco-button-stylable {
    color: #fff !important;
}

.d-addition__popup {
    top: unset !important;
    bottom: 92px;
    left: 830px !important;
}
}
